# Fingerly first-party proxy for nginx, version 1.0.0.
#
# Include this file inside the server block that serves your site, so the
# browser SDK posts to your own host:
#
#     server {
#         server_name www.example.com;
#         include /etc/nginx/snippets/fingerly.conf;
#         ...
#     }
#
# `/k7x2qm4a` is the path the Fingerly dashboard issued for this proxy. The
# location answers exactly that path, nothing under or beside it.

location = /k7x2qm4a {
    # The proxy key lives in its own file, readable only by root and kept out of
    # version control. It holds one line:
    #     set $fingerly_proxy_key "fly_px_...";
    include /etc/nginx/fingerly-proxy-key.conf;

    if ($request_method != POST) {
        add_header Allow "POST" always;
        add_header Cache-Control "no-store" always;
        return 405;
    }
    # A key that is not shaped like a proxy key answers 503 rather than
    # forwarding anything.
    if ($fingerly_proxy_key !~ "^fly_px_(production|staging|development)_[A-Za-z0-9_-]+$") {
        add_header Cache-Control "no-store" always;
        return 503;
    }

    # Browsers send Origin with every POST. The page's own origin stands in when
    # a client leaves it out.
    set $fingerly_origin $http_origin;
    if ($fingerly_origin = "") {
        set $fingerly_origin "$scheme://$http_host";
    }

    client_max_body_size 1m;

    # The one URL this location can reach. Both of the browser SDK's calls go
    # here; the API tells them apart by their bodies.
    proxy_pass https://api.fingerly.io/api/v1/ingest;
    proxy_http_version 1.1;
    proxy_ssl_server_name on;
    proxy_ssl_verify on;
    proxy_ssl_verify_depth 3;
    proxy_ssl_trusted_certificate /etc/ssl/certs/ca-certificates.crt;
    proxy_redirect off;
    proxy_connect_timeout 5s;
    proxy_send_timeout 5s;
    proxy_read_timeout 5s;

    # Request headers are an allowlist: nothing the visitor sent reaches the API
    # unless it is named here. Cookies, Authorization and any visitor-sent
    # X-Fingerly-* header are dropped by construction. An empty value is not
    # sent at all.
    proxy_pass_request_headers off;
    proxy_set_header Host api.fingerly.io;
    proxy_set_header Content-Type $content_type;
    proxy_set_header X-Api-Key $http_x_api_key;
    proxy_set_header Idempotency-Key $http_idempotency_key;
    proxy_set_header X-Fingerly-Proxy-Key $fingerly_proxy_key;
    # The address of the connection nginx accepted. Behind a load balancer, set
    # up the realip module so this is the visitor, not the load balancer.
    proxy_set_header X-Fingerly-Client-Ip $remote_addr;
    proxy_set_header X-Fingerly-Origin $fingerly_origin;
    proxy_set_header X-Fingerly-User-Agent $http_user_agent;
    proxy_set_header X-Fingerly-Proxy-Version "nginx/1.0.0";

    # The API sends nothing naming Fingerly to proxied callers; dropping cookies
    # and pinning the cache policy is defense in depth.
    proxy_hide_header Set-Cookie;
    proxy_hide_header Cache-Control;
    add_header Cache-Control "no-store" always;
}

server {
    server_name www.example.com;
    include /etc/nginx/snippets/fingerly.conf;
    # ...
}

